    char szRegVersion[100];
    long int nVerMajor;
    long int nVerMinor;
    D2ControlStrc* pForm4;
    D2ControlStrc* nFlagsOrForm5;
    D2Sound::Src::D2SoundSmp::CleanupSoundBuffer(0xb4);
