uint32_t __fastcall MAINMENU_DetectDoubleClick(D2ControlMsg * pMsg) {
    // Static local variables (originally global data)
    static int gnDoubleClickLastX; D2_STATIC_GUARD_BSS(gnDoubleClickLastX, "D2Launch::MainMenus::MAINMENU_DetectDoubleClick::gnDoubleClickLastX");
    static int gnDoubleClickLastY; D2_STATIC_GUARD_BSS(gnDoubleClickLastY, "D2Launch::MainMenus::MAINMENU_DetectDoubleClick::gnDoubleClickLastY");
    static unsigned int gdwDoubleClickLastTickCount; D2_STATIC_GUARD_BSS(gdwDoubleClickLastTickCount, "D2Launch::MainMenus::MAINMENU_DetectDoubleClick::gdwDoubleClickLastTickCount");

    tagPOINT cursorPos;
    uint32_t bIsDoubleClick = (uint32_t)(pMsg->uMsg == 0x201);
    uint32_t dwTick = GetTickCount();
    if ((int)(dwTick - gdwDoubleClickLastTickCount) > 300) {
      bIsDoubleClick = 0;
    }

    /* LPPOINT lpPoint for GetCursorPos */ GetCursorPos(&cursorPos);
    uint32_t nSignX = cursorPos.x - gnDoubleClickLastX >> 0x1f;
    uint32_t nSignY = cursorPos.y - gnDoubleClickLastY >> 0x1f;
    if ((int)((cursorPos.x - gnDoubleClickLastX ^ nSignX) - nSignX + ((cursorPos.y - gnDoubleClickLastY ^ nSignY) - nSignY)) > 4) {
      bIsDoubleClick = 0;
    }

    gnDoubleClickLastY = cursorPos.y;
    gdwDoubleClickLastTickCount = dwTick;
    gnDoubleClickLastX = cursorPos.x;
    return bIsDoubleClick;
}

void __stdcall UIMENU_ShowRealmNameOnButton() {
    int i;
    uint16_t awFormat[256];
    uint16_t awGatewayW[256];
    char szGateway[256];
    uint16_t awButtonText[256];
    D2BNetGatewayAccessStr* pGateway = (D2BNetGatewayAccessStr*)gpBNetCallbacks->pfnBnetLoadAndReturn();
    Storm::Source::SSTR::SStrCopy(szGateway, Bnclient::BNGatewayAccess::Name(pGateway, pGateway->nCurGatewayIdx), 0x100);
    for (i = 0; i < 0x100; i++) {
      awGatewayW[i] = L'\0';
    }

    D2Lang::UTF8_ConvertToWideChar(awGatewayW, szGateway, 0x100);
    for (i = 0; i < 0x100; i++) {
      awFormat[i] = L'\0';
    }

    uint16_t* pwScratch = D2Lang::StrTable::strtable::GetLocaleString(0x2b29);
    D2Lang::Unicode::UNISYS::STRING_CopyWideString(awFormat, pwScratch);
    for (i = 0; i < 0x100; i++) {
      awButtonText[i] = L'\0';
    }

    memset(awButtonText, 0, 0x100);
    D2Lang::Unicode::UNISYS::UNICODE_FormatWideString(0x100, awButtonText, awFormat, awGatewayW);
    i = 0;
    int32_t nLen = D2Lang::Unicode::UNISYS::STRING_GetWideStringLength(awButtonText);
    if (nLen > 0) {
      uint16_t wCh;
      do {
        wCh = awButtonText[i];
        if ((uint16_t)wCh < 0x100) {
          wCh = D2Client::UI::ui::CharacterLookupTable[(uint16_t)wCh];
        }

        awButtonText[i] = wCh;
        i++;
        nLen = D2Lang::Unicode::UNISYS::STRING_GetWideStringLength(awButtonText);
      } while (i < nLen);
    }

    D2Win::Src::D2WinButton::D2WINBUTTON_SetTextWithFont(gpCtlRealmNameButton, 10, awButtonText, 0);
}

