static BOOL MAINMENU_IsD2GSJoinErrorRecoverable(int32_t nErrorCode) {
    switch (nErrorCode) {
      case 2:

      case 10:

      case 0xb:

      case 0xc:

      case 0xd:

      case 0x7e:

      case 0x7f:
        return 1;
    }

    return 0;
}

uint32_t __stdcall MAINMENU_PollMCPThreadStatus() {
    BOOL bRecoverable;
    if (gnMCPConnectThreadHandle) {
      return 1;
    }

    HANDLE hHandle = D2Multi::McpConnect::GetMCPThread();
    if (!hHandle) {
      return 2;
    }

    DWORD dwWaitResult = 0;
    hHandle = D2Multi::McpConnect::GetMCPThread();
    /* HANDLE hHandle for WaitForSingleObject */ dwWaitResult = WaitForSingleObject(hHandle, dwWaitResult);
    if (dwWaitResult) {
      if (dwWaitResult != 0x102) {
        return 2;
      }

      return 3;
    }

    int32_t nJoinResult;
    nJoinResult = D2MCPClient::McpConnect::GetD2GSJoinResult();
    bRecoverable = MAINMENU_IsD2GSJoinErrorRecoverable(nJoinResult);
    return bRecoverable ? 2 : 0;
}

int __stdcall MAINMENU_PollMCPThreadStatusPump(int nFrameIndex) {
    if (gnMainMenuConnectFlag) {
      gnMCPConnectThreadHandle = 1;
    }

    uint32_t uVar1 = MAINMENU_PollMCPThreadStatus();
    if (uVar1 == 3) {
      return 1;
    }

    D2Win::Src::D2WinMain::D2WINMAIN_ClearMessageLoopFlag();
    return 1;
}

uint32_t __fastcall MAINMENU_ConnectToRealm(uint8_t * pszRealmName, int32_t bSilent) {
    int nCmp;
    int32_t nHasPeer;
    int* pnLogonResult;
    char* pszIniValue;
    uint32_t nResult;
    if (*pszRealmName) {
      uint8_t* pbName;
      pszIniValue = D2IniData_launcher->szCharacterRealm;
      pbName = pszRealmName;
      if (*pszIniValue != '\0') {
        nCmp = strcmp((char*)pbName, pszIniValue);
        if (!nCmp) {
          nHasPeer = D2MCPClient::McpConnect::HasPeerName();
          if (nHasPeer) {
            return 0;
          }
        }
      }
    }
    if (!bSilent) {
      UIMENU_PleaseWaitWithCancelButton();
    }

    D2MCPClient::McpConnect::FreeMCP();
    gnMCPConnectThreadHandle = 0;
    if (!*pszRealmName) {
      D2IniData_launcher->szCharacterRealm[0] = '\0';
      D2IniData_launcher->szREALM[0] = '\0';
      if (bSilent) {
        return 0;
      }

      FORMS_DestroyList();
      return 0;
    }
    if (gpBNetCallbacks) {
      pnLogonResult = (int*)gpBNetCallbacks->pfnSendLogonRealmEx((char*)pszRealmName, "password");
      if (pnLogonResult && *pnLogonResult != 8) {
        Storm::Source::SSTR::SStrCopy(D2IniData_launcher->szCharacterRealm, (char*)pszRealmName, 0x100);
        Storm::Source::SSTR::SStrCopy(D2IniData_launcher->szREALM, (char*)pszRealmName, 0x100);
        D2MCPClient::McpConnect::MCPCONNECT_CreateThread((uint32_t*)(pnLogonResult + 1));
        nResult = 3;
        if (bSilent) {
          return nResult;
        }

        D2Win::Src::D2WinMain::MessagePump(MAINMENU_PollMCPThreadStatusPump);
        nResult = MAINMENU_PollMCPThreadStatus();
        FORMS_DestroyList();
        return nResult;
      }
    }
    if (bSilent) {
      return 2;
    }

    FORMS_DestroyList();
    return 2;
}

