int __stdcall ClickOnClassCreate(D2ControlMsg * pControlMsg) {
    D2ControlStrc* pClickedAnim;
    int32_t nAnimState;
    nAnimState = D2Win::D2WINANIMIMAGE_GetCurrentState((::D2WinAnimImage*)pControlMsg->pControl);
    BOOL bIsExpansion;
    bIsExpansion = Fog::D2CheckExpansionGame();
    D2ControlStrc** ppAnimIter;
    ppAnimIter = gaAnimImgCharCreateByClass;
    if (bIsExpansion) {
      do {
        bIsExpansion = D2Win::D2WINANIMIMAGE_TryAdvanceToPlaying((::D2WinAnimImage*)*ppAnimIter);
        if (!bIsExpansion) {
          return 0;
        }

        ppAnimIter++;
      } while ((int)ppAnimIter < (intptr_t)((char*)&gaAnimImgCharCreateByClass + sizeof(gaAnimImgCharCreateByClass)));
    } else {
      do {
        bIsExpansion = D2Win::D2WINANIMIMAGE_TryAdvanceToPlaying((::D2WinAnimImage*)*ppAnimIter);
        if (!bIsExpansion) {
          return 0;
        }

        ppAnimIter++;
      } while ((int)ppAnimIter < (intptr_t)((char*)&gaAnimImgCharCreateByClass + 20));
    }

    int nPrevClassId;
    nPrevClassId = gnClassDescriptionTooltipState;
    int nNewClassId;
    nNewClassId = -1;
    bool bVar1;
    bVar1 = gnClassDescriptionTooltipState != -1;
    gnClassDescriptionTooltipState = -1;
    if (bVar1) {
      char* pszSoundFile;
      D2Sound::Src::D2SoundFast::SOUND_FadeOutAllSoundEffects();
      switch (nPrevClassId) {
        case 0:
          pszSoundFile = "data\\global\\sfx\\cursor\\intro\\amazon deselect.wav";
        break;
        case 4:
          pszSoundFile = "data\\global\\sfx\\cursor\\intro\\barbarian deselect.wav";
        break;
        case 3:
          pszSoundFile = "data\\global\\sfx\\cursor\\intro\\paladin deselect.wav";
        break;
        case 2:
          pszSoundFile = "data\\global\\sfx\\cursor\\intro\\necromancer deselect.wav";
        break;
        case 1:
          pszSoundFile = "data\\global\\sfx\\cursor\\intro\\sorceress deselect.wav";
        break;
        case 5:
          pszSoundFile = "data\\global\\sfx\\cursor\\intro\\druid deselect.wav";
        break;
        case 6:
          pszSoundFile = "data\\global\\sfx\\cursor\\intro\\assassin deselect.wav";
        break;
        default:
          goto identify_clicked_class;
      }

      D2Sound::Src::D2SoundFast::SOUND_PlaySoundEffect((uint8_t*)pszSoundFile);
    }

    identify_clicked_class:
    pClickedAnim = pControlMsg->pControl;
    if (pClickedAnim == gaAnimImgCharCreateByClass[0]) {
      nNewClassId = 4;
      MAINMENU_SetClassDescriptionTooltip(pControlMsg->uLParam.nLParam, 4, 0xfa7, 0x140a);
    } else if (pClickedAnim == gaAnimImgCharCreateByClass[1]) {
      nNewClassId = 2;
      MAINMENU_SetClassDescriptionTooltip(pControlMsg->uLParam.nLParam, 2, 0xfa9, 0x1409);
    } else if (pClickedAnim == gaAnimImgCharCreateByClass[2]) {
      nNewClassId = 0;
      MAINMENU_SetClassDescriptionTooltip(pControlMsg->uLParam.nLParam, 0, 0xfab, 0x1408);
    } else if (pClickedAnim == gaAnimImgCharCreateByClass[3]) {
      nNewClassId = 1;
      MAINMENU_SetClassDescriptionTooltip(pControlMsg->uLParam.nLParam, 1, 0xfaa, 0x140b);
    } else if (pClickedAnim == gaAnimImgCharCreateByClass[4]) {
      nNewClassId = 3;
      MAINMENU_SetClassDescriptionTooltip(pControlMsg->uLParam.nLParam, 3, 0xfa8, 0x140c);
    } else if (pClickedAnim == gaAnimImgCharCreateByClass[5]) {
      nNewClassId = 5;
      MAINMENU_SetDruidDescription((D2WinAnimImageNotifyStrc*)pControlMsg);
    } else if (pClickedAnim == gaAnimImgCharCreateByClass[6]) {
      nNewClassId = 6;
      MAINMENU_SetAssassinDescription((D2WinAnimImageNotifyStrc*)pControlMsg);
    }
    if (nNewClassId == nPrevClassId || nAnimState != 1) {
      if (nAnimState != 2 && nAnimState != 3 && nAnimState != 4) {
        gnClassDescriptionTooltipState = nNewClassId;
      }
    } else {
      switch (nNewClassId) {
        case 0:
          D2Sound::Src::D2SoundFast::SOUND_PlaySoundEffect((uint8_t*)"data\\global\\sfx\\cursor\\intro\\amazon select.wav");
        break;
        case 4:
          D2Sound::Src::D2SoundFast::SOUND_PlaySoundEffect((uint8_t*)"data\\global\\sfx\\cursor\\intro\\barbarian select.wav");
        break;
        case 3:
          D2Sound::Src::D2SoundFast::SOUND_PlaySoundEffect((uint8_t*)"data\\global\\sfx\\cursor\\intro\\paladin select.wav");
        break;
        case 2:
          D2Sound::Src::D2SoundFast::SOUND_PlaySoundEffect((uint8_t*)"data\\global\\sfx\\cursor\\intro\\necromancer select.wav");
        break;
        case 1:
          D2Sound::Src::D2SoundFast::SOUND_PlaySoundEffect((uint8_t*)"data\\global\\sfx\\cursor\\intro\\sorceress select.wav");
        break;
        case 6:
          D2Sound::Src::D2SoundFast::SOUND_PlaySoundEffect((uint8_t*)"data\\global\\sfx\\cursor\\intro\\assassin select.wav");
        break;
        case 5:
          D2Sound::Src::D2SoundFast::SOUND_PlaySoundEffect((uint8_t*)"data\\global\\sfx\\cursor\\intro\\druid select.wav");
        break;
      }

      gnClassDescriptionTooltipState = nNewClassId;
    }

    MAINMENU_SetSelectedClassInINI((eD2PlayerClassID)gnClassDescriptionTooltipState);
    if (gnClassDescriptionTooltipState == -1 && nAnimState != 1) {
      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(gpCtlCreateCharCancelButton, 0);
      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharOKButton->sControl, 0);
      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharHardcoreLabel->sControl, 0);
      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(gpCtlCreateCharHardcoreCheckbox, 0);
      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpaCharNameBuffers->sControl, 0);
      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(bCharacterCreationInProgress, 0);
      if (OogCurrentCharSelectionMode == CHAR_SELECTION_BNET) {
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharLadderLabel->sControl, 0);
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharLadderCheckbox->sControl, 0);
      }

      bIsExpansion = Fog::D2CheckExpansionGame();
      if (bIsExpansion) {
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharExpClassPanel->sControl, 0);
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharExpansionCheckbox->sControl, 0);
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(gpCtlCreateCharExpansionCheckboxImage, 0);
      }

      D2Win::Src::D2WinMain::D2WINMAIN_SetFocusedControl(nullptr);
      if (OogCurrentCharSelectionMode == CHAR_SELECTION_BNET) {
        bIsExpansion = 1;
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCharCreateBNetRealmTextBox->sControl, bIsExpansion);
      }
    } else {
      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(gpCtlCreateCharCancelButton, 1);
      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharOKButton->sControl, 1);
      if (nCharacterSelectionIndex) {
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharHardcoreLabel->sControl, 1);
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(gpCtlCreateCharHardcoreCheckbox, 1);
      }
      if (OogCurrentCharSelectionMode == CHAR_SELECTION_BNET) {
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharLadderLabel->sControl, 1);
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharLadderCheckbox->sControl, 1);
      }

      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpaCharNameBuffers->sControl, 1);
      D2Win::Src::D2WinMain::D2WINMAIN_SetFocusedControl(&gpaCharNameBuffers->sControl);
      D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(bCharacterCreationInProgress, 1);
      if (OogCurrentCharSelectionMode == CHAR_SELECTION_BNET) {
        bIsExpansion = 0;
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCharCreateBNetRealmTextBox->sControl, bIsExpansion);
      }
    }

    bIsExpansion = Fog::D2CheckExpansionGame();
    if (bIsExpansion) {
      if (gnClassDescriptionTooltipState == 6 || gnClassDescriptionTooltipState == 5) {
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharExpClassPanel->sControl, 1);
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharExpansionCheckbox->sControl, 0);
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(gpCtlCreateCharExpansionCheckboxImage, 1);
      } else {
        if (gnClassDescriptionTooltipState == -1) {
          goto apply_bnet_state;
        }

        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharExpClassPanel->sControl, 1);
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(&gpCtlCreateCharExpansionCheckbox->sControl, 1);
        D2Win::Src::D2WinMain::D2WINMAIN_SetControlActive(gpCtlCreateCharExpansionCheckboxImage, 0);
        D2Win::Src::D2WinButton::D2WINBUTTON_SetPressed(gpCtlCreateCharExpansionCheckbox, 1);
      }

      D2IniData_launcher->eCTEMP_eD2PlayerStatus |= PLAYERSTATUS_Expansion;
    }

    apply_bnet_state:
    if (OogCurrentCharSelectionMode == CHAR_SELECTION_BNET) {
      D2Win::Src::D2WinButton::D2WINBUTTON_SetPressed(gpCtlCreateCharLadderCheckbox, 1);
      D2IniData_launcher->eCTEMP_eD2PlayerStatus |= PLAYERSTATUS_Ladder;
    }
    return 1;
}

