// BNet login flow continuation. Checks gbPasswordChangeInProgress flag to determine if showing password change or normal login. Creates UI forms, validates credentials, dispatches to launcher subsystem.
BOOL __stdcall UIMENU_AndOneMorePleaseWait(D2ControlMsg * pControlMsg) {
    D2ControlStrc* pBgForm;
    D2ControlStrc* pMidForm;
    BOOL nTosResult;
    D2ControlStrc** ppForm;
    char szSavePath[1024];
    FORMS_PredefinedFormStrc* pTextFormDef;
    MAINMENU_SaveAccountAndPasswordToINI(&gpBnetAccountEditBox->sControl, &gpBnetPasswordEditBox->sControl);
    Fog::Source::SFile::GetAndCreateSavePath(szSavePath, 0x400);
    uint32_t nCharIdx;
    nCharIdx = 0;
    do {
      if (szSavePath[nCharIdx] == '\\') {
        szSavePath[nCharIdx + 1] = '\0';
        break;
      }

      nCharIdx++;
    } while (nCharIdx < 0x400);

    DWORD dwSectorsPerCluster;
    dwSectorsPerCluster = 0;
    DWORD dwBytesPerSector;
    dwBytesPerSector = 0;
    DWORD dwFreeClusters;
    dwFreeClusters = 0;
    DWORD dwTotalClusters;
    dwTotalClusters = 0;
    GetDiskFreeSpaceA(szSavePath, &dwSectorsPerCluster, &dwBytesPerSector, &dwFreeClusters, &dwTotalClusters);
    if (dwFreeClusters * dwBytesPerSector * dwSectorsPerCluster >= 5000) {
      nTosResult = UIMENU_ShowTermsOfService();
      return nTosResult;
    }

    uint16_t* wszWaitText;
    wszWaitText = D2Lang::StrTable::strtable::GetLocaleString(0x141d);
    int nFormIdx;
    nFormIdx = 0;
    if (FORMS_nListCount > 0) {
      ppForm = FORMS_pList;
      do {
        D2Win::Src::D2WinMain::FORMS_DestroyAnyForm(ppForm);
        nFormIdx++;
        ppForm++;
      } while (nFormIdx < FORMS_nListCount);
    }

    FORMS_nListCount = 0;
    if (gnIsFecharPalette) {
      ::D2WinTextBox* pTextForm;
      pBgForm = D2Win::Src::D2WinMain::FORMS_CreateAnyForm(gaPredefinedForms + 0xf7);
      FORMS_pList[FORMS_nListCount] = pBgForm;
      FORMS_nListCount++;
      D2Win::Src::D2WinMain::FORMS_SetGlobalFormImage(pBgForm, 1);
      if (FORMS_nListCount < 0x40) {
        pMidForm = D2Win::Src::D2WinMain::FORMS_CreateAnyForm(gaPredefinedForms + 0xf8);
        FORMS_pList[FORMS_nListCount] = pMidForm;
        FORMS_nListCount++;
        if (FORMS_nListCount < 0x40) {
          pTextFormDef = gaPredefinedForms + 0xf9;
          create_message_form:
          pTextForm = (::D2WinTextBox*)D2Win::Src::D2WinMain::FORMS_CreateAnyForm(pTextFormDef);
          FORMS_pList[FORMS_nListCount] = (D2ControlStrc*)pTextForm;
          FORMS_nListCount++;
          D2Win::Src::D2WinMain::SetUnsetFlag0x08(pBgForm, 1);
          D2Win::Src::D2WinMain::SetUnsetFlag0x08(pMidForm, 1);
          D2Win::Src::D2WinMain::SetUnsetFlag0x08((D2ControlStrc*)pTextForm, 1);
          MAINMENU_SetMultilineText(wszWaitText, pTextForm, 0, '\0');
          gpCurrentUIMenuInstance = MAINMENU_CloseAndLaunchCharSelect;
          return 1;
        }
      }
    } else {
      pBgForm = D2Win::Src::D2WinMain::FORMS_CreateAnyForm(gaPredefinedForms + 0xde);
      FORMS_pList[FORMS_nListCount] = pBgForm;
      FORMS_nListCount++;
      D2Win::Src::D2WinMain::FORMS_SetGlobalFormImage(pBgForm, 1);
      if (FORMS_nListCount < 0x40) {
        pMidForm = D2Win::Src::D2WinMain::FORMS_CreateAnyForm(gaPredefinedForms + 0xe1);
        FORMS_pList[FORMS_nListCount] = pMidForm;
        FORMS_nListCount++;
        if (FORMS_nListCount < 0x40) {
          pTextFormDef = gaPredefinedForms + 0xe0;
          goto create_message_form;
        }
      }
    }

    Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x610);
    exit(-1);
}

