int32_t __fastcall fAPPMODE_launcher_ReturnAppMode_Caller(D2IniConfigStrc * pD2IniData) {
    D2IniData_launcher = pD2IniData;
    D2IniConfigStrc* pSkipToOpen;
    pSkipToOpen = pD2IniData;
    D2Win::D2GFX::UI_Init();
    BOOL bIsExpansion;
    bIsExpansion = Fog::D2CheckExpansionGame();
    D2PoolManagerStrc* pStringArchive;
    pStringArchive = D2Win::Src::D2WinArchive::ReturnZero();
    int bSoundPlaying;
    bSoundPlaying = D2Lang::StrTable::strtable::TABLES_LoadStrings(pStringArchive, nullptr, bIsExpansion);
    if (!bSoundPlaying) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x125a);
      exit(-1);
    }

    IMAGE_LoadPredefinedImages();
    D2Win::Src::D2WinMain::D2WINMAIN_SetCursorDC6(DC6_CURSOR_ohand);
    D2IniData_launcher->padding_0x35F[2] = 0;
    D2IniData_launcher->padding_0x35F[0x22] = 0;
    D2IniData_launcher->szGAMENAME[0] = '\0';
    D2IniData_launcher->szGamePassword[0] = '\0';
    if (OogCurrentCharSelectionMode != CHAR_SELECTION_TCP_IP) {
      D2IniData_launcher->szSERVERIP[0] = '\0';
    }

    D2Sound::Src::D2SoundFast::SOUND_InitSoundEffectBuffers();
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\button.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\amazon select.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\amazon deselect.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\barbarian select.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\barbarian deselect.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\paladin select.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\paladin deselect.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\necromancer select.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\necromancer deselect.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\sorceress select.wav");
    D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\sorceress deselect.wav");
    bIsExpansion = Fog::D2CheckExpansionGame();
    if (bIsExpansion) {
      D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\druid select.wav");
      D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\druid deselect.wav");
      D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\assassin select.wav");
      D2Sound::Src::D2SoundFast::SOUND_LoadWavFile("data\\global\\sfx\\cursor\\intro\\assassin deselect.wav");
    }

    gpBNetCallbacks = pD2IniData->pBNetClientCallbacks;
    uint8_t nScreenToShow;
    nScreenToShow = D2IniData_launcher->nScreenToShow;
    if (nScreenToShow == 2) {
      bIsExpansion = gpBNetCallbacks->pfnIsSocketConnected();
      OogCurrentCharSelectionMode = CHAR_SELECTION_BNET;
      if (bIsExpansion) {
        D2Win::D2GFX::D2GFX_SetVideoMode(1);
        CharSel::UIMENU_CharacterSelectAllGameTypes();
        goto run_menu_loop;
      }
    } else {
      if (nScreenToShow != 4) {
        if (nScreenToShow == 3) {
          Launcher::LAUNCHER_InitNetworkLobbyQueue(D2IniData_launcher);
          OogCurrentCharSelectionMode = CHAR_SELECTION_TCP_IP;
          D2Win::D2GFX::D2GFX_SetVideoMode(1);
          UIMENU_TCPIPOptions();
        } else {
          Launcher::LAUNCHER_InitNetworkLobbyQueue(D2IniData_launcher);
          if (D2IniData_launcher->bSKIPTOBNET) {
            pSkipToOpen = 0;
            Storm::Source::SReg::SRegLoadValue("Diablo II", "Skip To Open", 0, (int32_t*)&pSkipToOpen);
            D2IniData_launcher->bSKIPTOBNET = false;
            D2IniData_launcher->padding_0x35F[0] = 1;
            D2Win::D2GFX::D2GFX_SetVideoMode(1);
            D2gfx::D2GFX::D2GFX_UpdateWindowSize(1);
            OogCurrentCharSelectionMode = (uint32_t)(pSkipToOpen != 0) * 2 + CHAR_SELECTION_BNET;
            UIMENU_MainMenuAgain();
          } else {
            OogCurrentCharSelectionMode = CHAR_SELECTION_SP;
            if (!D2IniData_launcher->padding_0x35F[0]) {
              D2Win::D2GFX::D2GFX_SetVideoMode(1);
              D2gfx::D2GFX::D2GFX_UpdateWindowSize(1);
              /* Show intro and first screen without menus */ PlaysBlizzardNorthCutScene();
              D2IniData_launcher->padding_0x35F[0] = 1;
            } else {
              D2Win::D2GFX::D2GFX_SetVideoMode(1);
              UIMENU_MainMenu();
            }
          }
        }

        goto run_menu_loop;
      }

      bIsExpansion = gpBNetCallbacks->pfnIsSocketConnected();
      OogCurrentCharSelectionMode = CHAR_SELECTION_BNET_OPEN_Unsure;
      if (bIsExpansion) {
        D2Win::D2GFX::D2GFX_SetVideoMode(1);
        CharSel::UIMENU_CharacterSelectAllGameTypes();
        goto run_menu_loop;
      }
    }

    D2Win::D2GFX::D2GFX_SetVideoMode(1);
    UIMENU_MainMenuAgain();
    run_menu_loop:
    D2Win::Src::D2WinMain::D2WINMAIN_SetExitCallback(LAUNCHER_SetExitAppModeResult);
    D2Win::Src::D2WinMain::MessagePump(MAINMENU_ReturnTrue);
    D2Sound::Src::D2SoundFast::SOUND_FadeOutAllSoundEffects();
    bSoundPlaying = D2Sound::Src::D2SoundFast::SOUND_IsAnySoundEffectPlaying();
    while (bSoundPlaying) {
      /* DWORD dwMilliseconds for Sleep */ Sleep(0);
      bSoundPlaying = D2Sound::Src::D2SoundFast::SOUND_IsAnySoundEffectPlaying();
    }

    D2Sound::Src::D2SoundFast::SOUND_FreeSoundEffectBuffers();
    FORMS_DestroyLists();
    IMAGE_FreePredefinedImages();
    D2Lang::StrTable::strtable::STRINGTABLE_FreeStringTables();
    D2IniConfigStrc* pIniData = D2IniData_launcher;
    memset(pIniData->szLastKnownIpTcpIp, 0, 24 * sizeof(pIniData->szLastKnownIpTcpIp[0]));
    D2Win::Src::D2WinMain::FreeInGameGFX();
    return gnSelectedCharGameState;
}

